#!/usr/bin/env python3
"""main.py – Copies entry.png to the Makefun output directory."""
import os
import shutil
from pathlib import Path

# The entry.png is generated by gen_news.py in the repo root
SOURCE = Path(__file__).parent / "entry.png"

# Output directory: MAKEFUN_OUTPUT_DIR env var or default /output
TARGET_DIR = Path(os.environ.get("MAKEFUN_OUTPUT_DIR", "/output"))
TARGET = TARGET_DIR / "entry.png"

def main() -> None:
    TARGET_DIR.mkdir(parents=True, exist_ok=True)
    shutil.copy2(str(SOURCE), str(TARGET))
    print(f"Copied entry.png to {TARGET}")

if __name__ == "__main__":
    main()